{"command":"cat <<'EOF' > main.go
package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"strings"

	"github.com/gdamore/tcell/v2"
	"github.com/mattn/go-runewidth"
)

func main() {
	// Simple argument parsing for now
	var filename string
	if len(os.Args) > 1 {
		filename = os.Args[1]
	}

	var input io.Reader
	if filename != "" && filename != "-" {
		f, err := os.Open(filename)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error opening file: %v\n", err)
			os.Exit(1)
		}
		defer f.Close()
		input = f
	} else {
		input = os.Stdin
	}

	lines := []string{}
	scanner := bufio.NewScanner(input)
	for scanner.Scan() {
		lines = append(lines, scanner.Text())
	}

	if err := scanner.Err(); err != nil {
		fmt.Fprintf(os.Stderr, "Error reading input: %v\n", err)
		os.Exit(1)
	}

	// Start TUI
	s, err := tcell.NewScreen()
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error creating screen: %v\n", err)
		os.Exit(1)
	}
	if err := s.Init(); err != nil {
		fmt.Fprintf(os.Stderr, "Error initializing screen: %v\n", err)
		os.Exit(1)
	}
	defer s.Fini()

	query := ""
	cursorPos := 0
	selectedLine := 0

	for {
		s.Clear()

		filtered := []string{}
		for _, line := range lines {
			if strings.Contains(strings.ToLower(line), strings.ToLower(query)) {
				filtered = append(filtered, line)
			}
		}

		if selectedLine >= len(filtered) {
			selectedLine = len(filtered) - 1
		}
		if selectedLine < 0 {
			selectedLine = 0
		}

		// Draw query
		prompt := "QUERY> "
		drawText(s, 0, 0, tcell.StyleDefault, prompt)
		drawText(s, len(prompt), 0, tcell.StyleDefault.Foreground(tcell.ColorYellow), query)

		// Draw status
		status := fmt.Sprintf("IgnoreCase [%d (1/1)]", len(filtered))
		w, _ := s.Size()
		drawText(s, w-len(status), 0, tcell.StyleDefault, status)

		// Draw lines
		for i, line := range filtered {
			if i + 1 >= 25 { // Simple height limit for now
				break
			}
			style := tcell.StyleDefault
			if i == selectedLine {
				style = style.Reverse(true)
			}
			drawText(s, 0, i+1, style, line)
		}

		s.Show()

		ev := s.PollEvent()
		switch ev := ev.(type) {
		case *tcell.EventKey:
			if ev.Key() == tcell.KeyEscape || ev.Key() == tcell.KeyCtrlC {
				return
			} else if ev.Key() == tcell.KeyEnter {
				s.Fini()
				if len(filtered) > 0 {
					fmt.Println(filtered[selectedLine])
				}
				return
			} else if ev.Key() == tcell.KeyBackspace || ev.Key() == tcell.KeyBackspace2 {
				if cursorPos > 0 {
					query = query[:cursorPos-1] + query[cursorPos:]
					cursorPos--
				}
			} else if ev.Key() == tcell.KeyRune {
				query = query[:cursorPos] + string(ev.Rune()) + query[cursorPos:]
				cursorPos++
			} else if ev.Key() == tcell.KeyUp || ev.Key() == tcell.KeyCtrlP {
				selectedLine--
			} else if ev.Key() == tcell.KeyDown || ev.Key() == tcell.KeyCtrlN {
				selectedLine++
			}
		case *tcell.EventResize:
			s.Sync()
		}
	}
}

func drawText(s tcell.Screen, x, y int, style tcell.Style, text string) {
	for _, r := range text {
		var width = runewidth.RuneWidth(r)
		s.SetContent(x, y, r, nil, style)
		x += width
	}
}
EOF
"}

