{"command":"cat <<'EOF' > raw.go
package main

import (
	"fmt"
	"os"
	"syscall"
	"unsafe"
)

func main() {
	fd := int(os.Stdin.Fd())
	var termios syscall.Termios
	if _, _, err := syscall.Syscall6(syscall.SYS_IOCTL, uintptr(fd), uintptr(syscall.TCGETS), uintptr(unsafe.Pointer(&termios)), 0, 0, 0); err != 0 {
		panic(err)
	}

	old := termios
	termios.Iflag &^= syscall.IGNBRK | syscall.BRKINT | syscall.PARMRK | syscall.ISTRIP | syscall.INLCR | syscall.IGNCR | syscall.ICRNL | syscall.IXON
	termios.Oflag &^= syscall.OPOST
	termios.Lflag &^= syscall.ECHO | syscall.ECHONL | syscall.ICANON | syscall.ISIG | syscall.IEXTEN
	termios.Cflag &^= syscall.CSIZE | syscall.PARENB
	termios.Cflag |= syscall.CS8
	termios.Cc[syscall.VMIN] = 1
	termios.Cc[syscall.VTIME] = 0

	if _, _, err := syscall.Syscall6(syscall.SYS_IOCTL, uintptr(fd), uintptr(syscall.TCSETS), uintptr(unsafe.Pointer(&termios)), 0, 0, 0); err != 0 {
		panic(err)
	}
	defer syscall.Syscall6(syscall.SYS_IOCTL, uintptr(fd), uintptr(syscall.TCSETS), uintptr(unsafe.Pointer(&old)), 0, 0, 0)

	fmt.Print("Raw mode. Press 'q' to quit.\r\n")
	buf := make([]byte, 16)
	for {
		n, _ := os.Stdin.Read(buf)
		fmt.Printf("Read %d bytes: %v\r\n", n, buf[:n])
		if n == 1 && buf[0] == 'q' {
			break
		}
	}
}
EOF
go build -o raw raw.go
"}

