{"command":"cat <<'EOF' > main.go
package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"regexp"
	"strings"
	"syscall"
	"unsafe"
)

type FilterMode int

const (
	IgnoreCase FilterMode = iota
	CaseSensitive
	SmartCase
	RegexpMode
	FuzzyMode
)

func (m FilterMode) String() string {
	switch m {
	case IgnoreCase: return "IgnoreCase"
	case CaseSensitive: return "CaseSensitive"
	case SmartCase: return "SmartCase"
	case RegexpMode: return "Regexp"
	case FuzzyMode: return "Fuzzy"
	}
	return ""
}

func main() {
	// Options
	var initialQuery string
	var layout = "top-down"
	var prompt = "QUERY> "
	// ... other options

	args := os.Args[1:]
	files := []string{}
	for i := 0; i < len(args); i++ {
		arg := args[i]
		if arg == "--query" && i+1 < len(args) {
			initialQuery = args[i+1]
			i++
		} else if strings.HasPrefix(arg, "--query=") {
			initialQuery = strings.TrimPrefix(arg, "--query=")
		} else if arg == "--layout" && i+1 < len(args) {
			layout = args[i+1]
			i++
		} else if strings.HasPrefix(arg, "--layout=") {
			layout = strings.TrimPrefix(arg, "--layout=")
		} else if arg == "--prompt" && i+1 < len(args) {
			prompt = args[i+1]
			i++
		} else if strings.HasPrefix(arg, "--prompt=") {
			prompt = strings.TrimPrefix(arg, "--prompt=")
		} else if arg == "--version" {
			fmt.Println("peco version v0.5.11 (built with go1.25.0)")
			return
		} else if arg == "-h" || arg == "--help" {
			showHelp()
			return
		} else if !strings.HasPrefix(arg, "-") {
			files = append(files, arg)
		}
	}

	var input io.Reader
	if len(files) > 0 && files[0] != "-" {
		f, err := os.Open(files[0])
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error opening file: %v\n", err)
			os.Exit(1)
		}
		defer f.Close()
		input = f
	} else {
		input = os.Stdin
	}

	lines := []string{}
	scanner := bufio.NewScanner(input)
	for scanner.Scan() {
		lines = append(lines, scanner.Text())
	}

	runTUI(lines, initialQuery, layout, prompt)
}

func showHelp() {
	fmt.Print(`
Usage: peco [options] [FILE]

Options:
  -h, --help            show this help message and exit
  --query               initial value for query
  --rcfile              path to the settings file
  --version             print the version and exit
  -b, --buffer-size     number of lines to keep in search buffer
  --null                expect NUL (\0) as separator for target/output
  --initial-index       position of the initial index of the selection (0 base)
  --initial-filter      specify the default filter
  --prompt              specify the prompt string
  --layout              layout to be used. 'top-down', 'bottom-up', or 'top-down-query-bottom'. default is 'top-down'
  --select-1            select first item and immediately exit if the input contains only 1 item
  --exit-0              exit immediately with status 1 if the input is empty
  --select-all          select all items and immediately exit
  --on-cancel           specify action on user cancel. 'success' or 'error'.
                        default is 'success'. This may change in future versions
  --selection-prefix    use a prefix instead of changing line color to indicate currently selected lines.
                        default is to use colors. This option is experimental
  --exec                execute command instead of finishing/terminating peco.
                        Please note that this command will receive selected line(s) from stdin,
                        and will be executed via '/bin/sh -c' or 'cmd /c'
  --print-query         print out the current query as first line of output
  --ansi                enable ANSI color code support
  --height              display height in lines or percentage (e.g. '10', '50%')
`)
}

type winsize struct {
	Row    uint16
	Col    uint16
	Xpixel uint16
	Ypixel uint16
}

func getWinSize() (int, int) {
	var ws winsize
	syscall.Syscall(syscall.SYS_IOCTL, uintptr(syscall.Stdin), uintptr(syscall.TIOCGWINSZ), uintptr(unsafe.Pointer(&ws)))
	return int(ws.Row), int(ws.Col)
}

func runTUI(lines []string, initialQuery, layout, prompt string) {
	fd := int(os.Stdin.Fd())
	var termios syscall.Termios
	syscall.Syscall6(syscall.SYS_IOCTL, uintptr(fd), uintptr(syscall.TCGETS), uintptr(unsafe.Pointer(&termios)), 0, 0, 0)
	old := termios
	termios.Lflag &^= syscall.ECHO | syscall.ICANON | syscall.ISIG
	syscall.Syscall6(syscall.SYS_IOCTL, uintptr(fd), uintptr(syscall.TCSETS), uintptr(unsafe.Pointer(&termios)), 0, 0, 0)
	defer syscall.Syscall6(syscall.SYS_IOCTL, uintptr(fd), uintptr(syscall.TCSETS), uintptr(unsafe.Pointer(&old)), 0, 0, 0)

	// Switch to alternate screen
	fmt.Print("\033[?1049h")
	defer fmt.Print("\033[?1049l")

	query := initialQuery
	selectedLine := 0
	filterMode := IgnoreCase

	for {
		rows, cols := getWinSize()
		filtered := filterLines(lines, query, filterMode)

		if selectedLine >= len(filtered) {
			selectedLine = len(filtered) - 1
		}
		if selectedLine < 0 {
			selectedLine = 0
		}

		// Clear screen
		fmt.Print("\033[H\033[2J")

		status := fmt.Sprintf("%s [%d (1/1)]", filterMode.String(), len(filtered))

		var queryRow, listStartRow, listDir int
		if layout == "bottom-up" {
			queryRow = rows - 1
			listStartRow = rows - 2
			listDir = -1
		} else if layout == "top-down-query-bottom" {
			queryRow = rows - 1
			listStartRow = 0
			listDir = 1
		} else { // top-down
			queryRow = 0
			listStartRow = 1
			listDir = 1
		}

		// Draw Query
		fmt.Printf("\033[%d;1H", queryRow+1)
		fmt.Print("\033[1;32m" + prompt + "\033[0m")
		fmt.Printf("\033[1;33m%s\033[0m", query)

		// Draw status
		fmt.Printf("\033[%d;%dH%s", queryRow+1, cols-len(status)+1, status)

		// Draw List
		numLinesToDraw := rows - 1
		for i := 0; i < numLinesToDraw && i < len(filtered); i++ {
			row := listStartRow + (i * listDir)
			if row < 0 || row >= rows || (row == queryRow) {
				continue
			}
			fmt.Printf("\033[%d;1H", row+1)
			style := ""
			if i == selectedLine {
				style = "\033[7m" // Reverse
			}
			line := filtered[i]
			if len(line) > cols {
				line = line[:cols]
			}
			fmt.Print(style + line + "\033[0m")
		}

		// Move cursor to query
		fmt.Printf("\033[%d;%dH", queryRow+1, len(prompt)+len(query)+1)

		// Read key
		buf := make([]byte, 16)
		n, _ := os.Stdin.Read(buf)
