		res = strings.Contains(strings.ToLower(line), strings.ToLower(term))
	case CaseSensitive:
		res = strings.Contains(line, term)
	case SmartCase:
		hasUpper := false
		for _, r := range term { if r >= 'A' && r <= 'Z' { hasUpper = true; break } }
