		} else if buf[0] == 6 { if st.cursorPos < len(st.query) { st.cursorPos++ } // Ctrl-F
		} else if buf[0] == 2 { if st.cursorPos > 0 { st.cursorPos-- } // Ctrl-B
		} else if buf[0] == 4 { // Ctrl-D
