	case FuzzyMode: res = fuzzyMatch(line, term)
	}
	if negative { return !res }
	return res
}

func fuzzyMatch(line, term string) bool {
	lt, tt := strings.ToLower(line), strings.ToLower(term)
	i := 0
	for j := 0; j < len(lt) && i < len(tt); j++ { if lt[j] == tt[i] { i++ } }
	return i == len(tt)
}

